pub(super) fn component_frame(character: Character, index: u16) -> SpriteFrame {
    match character {
        Character::DeeJay => DEE_JAY_COMPONENTS[index as usize],
        Character::Rose => ROSE_COMPONENTS[index as usize],
        Character::FeiLong => FEI_LONG_COMPONENTS[index as usize],
        Character::Cammy => CAMMY_COMPONENTS[index as usize],
    }
}
